"use client";

import { m, useReducedMotion } from "framer-motion";
import { origin, geez } from "@/content/site";
import { asset } from "@/lib/asset";
import map from "@/content/world-map.json";

/**
 * A real world map (Natural Earth, generated by scripts/build-world-map.mjs)
 * with the great-circle route from Ethiopia to 4160 University Ave drawn on view.
 * The map image and this overlay share the same 1000×520 projection space.
 */
export function Journey() {
  const reduce = useReducedMotion();
  const draw = reduce
    ? {}
    : {
        initial: { pathLength: 0 },
        whileInView: { pathLength: 1 },
        viewport: { once: true, amount: 0.5 },
        transition: { duration: 2.6, ease: [0.33, 1, 0.68, 1] as const },
      };
  const [sx, sy] = map.sanDiego;
  const [ex, ey] = map.ethiopia;

  return (
    <figure className="relative self-center overflow-hidden rounded-[28px] bg-bean p-4 text-cotton sm:p-8">
      <div className="relative w-full" style={{ aspectRatio: `${map.width} / ${map.height}` }}>
        {/* eslint-disable-next-line @next/next/no-img-element */}
        <img src={asset("/world-map.svg")} alt="" loading="lazy" decoding="async" className="absolute inset-0 h-full w-full" />
        <svg viewBox={`0 0 ${map.width} ${map.height}`} className="absolute inset-0 h-full w-full" role="img" aria-labelledby="journey-title">
          <title id="journey-title">World map with a line drawn from Ethiopia to 4160 University Ave in City Heights, San Diego</title>
          <path d={map.route} fill="none" stroke="var(--cotton)" strokeOpacity="0.2" strokeWidth="2" strokeDasharray="3 8" />
          <m.path d={map.route} fill="none" stroke="var(--gold)" strokeWidth="3.5" strokeLinecap="round" {...draw} />

          <g transform={`translate(${ex} ${ey})`}>
            <circle r="6" fill="var(--gold)" stroke="var(--bean)" strokeWidth="2" />
            <text x="34" y="34" textAnchor="start" fontFamily="var(--font-geez)" fontSize="36" fontWeight="600" fill="var(--gold)" lang="am">
              {geez.buna.am}
            </text>
          </g>
          <g transform={`translate(${sx} ${sy})`}>
            <circle r="22" fill="var(--gold)" opacity="0.2" />
            <circle r="8" fill="var(--gold)" stroke="var(--bean)" strokeWidth="2" />
          </g>
        </svg>
      </div>
      <figcaption className="mt-4 grid grid-cols-2 gap-6 px-2 pb-2 text-sm sm:mt-6">
        <div>
          <p className="font-display text-2xl leading-tight text-gold">{origin.journeyTo.en}</p>
          <p className="mt-1 text-cotton/80">{origin.journeyToSub.en}</p>
        </div>
        <div className="text-right">
          <p className="font-display text-2xl leading-tight text-cotton">{origin.journeyFrom.en}</p>
          <p className="mt-1 text-cotton/80">Where coffee began</p>
        </div>
      </figcaption>
    </figure>
  );
}
